106	// TestOpenDuplicateSampleFailsWholeFile 文件里另有完全正常的样品时，也不能
107	// 只加载正常部分：整份打开失败、返回 nil Store、原文件保持原样
108	// （mustRejectOpen 已断言文件字节不变）。
109	func TestOpenDuplicateSampleFailsWholeFile(t *testing.T) {
110		path := writeRawLedger(t, `{
111		  "version": 1,
112		  "samples": {
113		    `+rawSampleOK+`,
114		    "S-001": {`+rawSampleS001Zhang+`},
115		    "S-001": {`+rawSampleS001Li+`}
116		  },
117		  "transfers": {}
118		}`)
119		mustRejectOpen(t, path, "S-001", "出现多次")
