122	// TestOpenRejectsDuplicateAcrossTwoSamplesFields 文件顶层有两个同名 samples
123	// 字段，S-001 分别在两个字段里各保存一次。标准库解码重复字段时只保留最后
124	// 一个字段的整张表，唯一性判断必须覆盖整份文件里的全部样品集合。
125	func TestOpenRejectsDuplicateAcrossTwoSamplesFields(t *testing.T) {
