138	
139	// TestOpenRejectsDuplicateSampleAcrossFieldsSeparatedByTopLevelFields 两个同名
140	// samples 字段之间隔着其他顶层字段、第二个字段内还隔着其他编号的样品，
141	// 重复编号同样不能漏过。
142	func TestOpenRejectsDuplicateSampleAcrossFieldsSeparatedByTopLevelFields(t *testing.T) {
