156	}
157	
158	// TestOpenRejectsDuplicateSampleAcrossFieldsViaUnicodeEscape 分处两个字段的
159	// 编号经 JSON 解码后是同一文字（其中一个首字符写成 U+0053 转义）时仍算重复。
160	func TestOpenRejectsDuplicateSampleAcrossFieldsViaUnicodeEscape(t *testing.T) {
161		path := writeRawLedger(t, `{
162		  "version": 1,
163		  "samples": {
164		    `+escapedS001+`: {`+rawSampleS001Zhang+`}
165		  },
166		  "samples": {
167		    "S-001": {`+rawSampleS001Li+`}
168		  },
169		  "transfers": {}
170		}`)
171		mustRejectOpen(t, path, "S-001", "出现多次")
172	}
173	
174	// TestOpenMergesDistinctSampleIDsAcrossDuplicateSamplesFields 多个同名 samples
175	// 字段分别只含不同编号时，不应仅因字段重名就报编号冲突：各条记录合并恢复，
176	// 仍能按编号查询到各自的数量与保管信息。
177	func TestOpenMergesDistinctSampleIDsAcrossDuplicateSamplesFields(t *testing.T) {
178		path := writeRawLedger(t, `{
179		  "version": 1,
180		  "samples": {
181		    "S-001": {`+rawSampleS001Zhang+`}
182		  },
183		  "samples": {
184		    `+rawSampleOK+`
185		  },
186		  "transfers": {}
187		}`)
188		s, err := Open(path)
