198		}
199		if p.InitialQty != "10.000" || p.Remaining != "10.000" || p.Holder != "张三" || p.Location != "实验室A" {
200			t.Fatalf("S-001 的数量与保管信息应完整保留: %+v", p)
201		}
202		ok, err := s.GetSample("OK")
203		if err != nil {
