211	// TestOpenMergesDistinctSampleIDsAcrossFieldsWithNullBetween 后一个 samples
212	// 字段为 null 不应清空前一个字段已经保存的样品；中间插入的其他顶层字段
213	// 也不影响合并恢复。
214	func TestOpenMergesDistinctSampleIDsAcrossFieldsWithNullBetween(t *testing.T) {
215		path := writeRawLedger(t, `{
216		  "version": 1,
217		  "samples": {
218		    "S-001": {`+rawSampleS001Zhang+`},
219		    `+rawSampleOK+`
220		  },
221		  "note": "中间字段",
222		  "samples": null,
