224		}`)
225		s, err := Open(path)
226		if err != nil {
227			t.Fatalf("后一个 samples 为 null 不应影响前一个字段的记录: %v", err)
228		}
229		if len(s.data.Samples) != 2 {
230			t.Fatalf("前一个字段的两份样品都应保留, got %d 份", len(s.data.Samples))
231		}
232	}
233	
234	// TestOpenDoesNotTreatSampleIDReferencesAsDuplicate 编号文字只出现在子样来源、
235	// 子样列表、交接关联或保管历史说明（含 Unicode 转义写法）中，而样品集合的键
236	// 各自不同，不能误报为重复。父样与子样各有独立编号，正常恢复。
237	func TestOpenDoesNotTreatSampleIDReferencesAsDuplicate(t *testing.T) {
238		path := writeRawLedger(t, `{
239		  "version": 1,
240		  "samples": {
241		    "S-001": {"id":"S-001","initial":10000,"remaining":6000,"holder":"张三","location":"实验室A","children":["S-001-A"],"history":[
242		      {"kind":"register","time":"2026-10-02T09:00:00Z","holder":"张三","location":"实验室A"},
243		      {"kind":"split","time":"2026-10-02T10:00:00Z","holder":"张三","location":"实验室A","detail":"分装创建子样 S-001-A（转义写法 `+escapedS001InText+`-A），来源是 S-001"}
244		    ]},
245		    "S-001-A": {"id":"S-001-A","parentId":"S-001","initial":4000,"remaining":4000,"holder":"张三","location":"实验室A","children":[],"history":[
246		      {"kind":"split","time":"2026-10-02T10:00:00Z","holder":"张三","location":"实验室A","detail":"由样品 S-001 分装"}
247		    ]}
248		  },
249		  "transfers": {
250		    "TR-001": {"id":"TR-001","sampleId":"S-001-A","fromHolder":"张三","fromLocation":"实验室A","toHolder":"李四","toLocation":"实验室B","qty":4000,"handedOverAt":"2026-10-03T10:00:00Z","confirmed":true,"receivedAt":"2026-10-03T11:00:00Z","confirmedBy":"李四"}
251		  }
252		}`)
253		s, err := Open(path)
254		if err != nil {
255			t.Fatalf("编号仅在来源、子样列表、交接关联或说明文字中出现不应判为重复: %v", err)
256		}
257		parent, err := s.GetSample("S-001")
258		if err != nil {
259			t.Fatal(err)
260		}
261		if len(parent.Children) != 1 || parent.Children[0] != "S-001-A" {
262			t.Fatalf("父子关系应正常恢复: %+v", parent)
263		}
264		child, err := s.GetSample("S-001-A")
265		if err != nil {
266			t.Fatal(err)
267		}
268		if child.ParentID != "S-001" {
269			t.Fatalf("子样来源应正常恢复: %+v", child)
270		}
271	}
272	
273	// TestOpenDistinctSampleIDsWithSameDetailsNotDuplicate 父样和子样（或不同
274	// 原样）编号不同，即使人员、地点或数量相同也不能被认定为重复。
275	func TestOpenDistinctSampleIDsWithSameDetailsNotDuplicate(t *testing.T) {
276		path := writeRawLedger(t, `{
277		  "version": 1,
278		  "samples": {
279		    "S-001": {"id":"S-001","initial":5000,"remaining":5000,"holder":"张三","location":"实验室A","children":[],"history":[]},
280		    "S-002": {"id":"S-002","initial":5000,"remaining":5000,"holder":"张三","location":"实验室A","children":[],"history":[]}
281		  },
282		  "transfers": {}
283		}`)
284		s, err := Open(path)
285		if err != nil {
286			t.Fatalf("编号不同、内容相同的样品不应判为重复: %v", err)
287		}
288		if len(s.data.Samples) != 2 {
289			t.Fatalf("两份样品都应保留, got %d 份", len(s.data.Samples))
290		}
291	}
292	
293	// TestOpenDuplicateSampleErrorIsInvalid 单独固定错误分类：重复样品编号错误
294	// 必须能被 errors.Is 判定为 ErrInvalid（而非解码错误或冲突类）。
295	func TestOpenDuplicateSampleErrorIsInvalid(t *testing.T) {
296		path := writeRawLedger(t, `{
297		  "version": 1,
298		  "samples": {
299		    "S-001": {`+rawSampleS001Zhang+`},
300		    "S-001": {`+rawSampleS001Li+`}
301		  },
302		  "transfers": {}
303		}`)
304		s, err := Open(path)
305		if s != nil {
306			t.Fatalf("打开失败必须返回 nil Store")
307		}
308		if !errors.Is(err, ErrInvalid) {
309			t.Fatalf("重复样品编号应判定为 ErrInvalid, got %v", err)
310		}
311		if errors.Is(err, ErrConflict) {
312			t.Fatalf("重复样品编号不应归类为 ErrConflict: %v", err)
313		}
314	}
