345	// 必须能被 errors.Is 判定为 ErrInvalid（而非解码错误或冲突类）。
346	func TestOpenDuplicateTransferErrorIsInvalid(t *testing.T) {
347		path := writeRawLedger(t, `{
348	  "version": 1,
349	  "samples": {`+rawSampleS1TwoHandovers+`},
350	  "transfers": {
351	    "TR-001": {`+rawTR001Confirmed+`},
