package custody

import (
	"errors"
	"testing"
)

func TestZZScratchCrossTypeSameID(t *testing.T) {
	path := writeRawLedger(t, `{
	  "version": 1,
	  "samples": {"X": {"id":"X","initial":1000,"remaining":1000,"holder":"张三","location":"A","children":[],"history":[]}},
	  "transfers": {"X": {"id":"X","sampleId":"X","fromHolder":"张三","fromLocation":"A","toHolder":"李四","toLocation":"B","qty":1000,"handedOverAt":"2026-10-02T10:00:00Z","confirmed":true,"receivedAt":"2026-10-02T11:00:00Z","confirmedBy":"李四"}}
	}`)
	s, err := Open(path)
	if err != nil {
		t.Fatalf("样品与交接碰巧同编号应正常打开: %v", err)
	}
	if _, err := s.GetSample("X"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.GetTransfer("X"); err != nil {
		t.Fatal(err)
	}
}

func TestZZScratchArrayRejected(t *testing.T) {
	for _, c := range []string{
		`{"version":1,"samples":[]}`,
		`{"version":1,"samples":{},"transfers":[]}`,
		`{"version":1,"samples":{},"transfers":{},"samples":[]}`,
	} {
		p := writeRawLedger(t, c)
		s, err := Open(p)
		if err == nil || s != nil || errors.Is(err, ErrInvalid) && false {
			t.Fatalf("数组集合必须拒绝, got s=%v err=%v", s, err)
		}
	}
